    float2 he = float2(abs((2.0 * h.x - h.y) - depth_c), abs((2.0 * h.z - h.w) - depth_c));
    float2 ve = float2(abs((2.0 * v.x - v.y) - depth_c), abs((2.0 * v.z - v.w) - depth_c));
    int h_sign = he.x < he.y ? -1 : 1;
    int v_sign = ve.x < ve.y ? -1 : 1;
