    float3 view_h = view_position(float3(((float)(p.x + h_sign) + 0.5) / size.x,
                                         ((float)p.y + 0.5) / size.y, h_sign < 0 ? h.x : h.z));
    float3 view_v = view_position(float3(((float)p.x + 0.5) / size.x,
                                         ((float)(p.y + v_sign) + 0.5) / size.y,
                                         v_sign < 0 ? v.x : v.z));
